<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><div class="page"><h1>Orders</h1><?php if ($error): ?><p role="alert"><?= esc($error) ?></p><?php endif ?><form class="admin-form" method="get" action="<?= site_url($prefix . '/orders') ?>"><label>Order number<input name="q" type="search" value="<?= esc($query) ?>"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach ($statuses as $option): ?><option value="<?= esc($option) ?>" <?= $status === $option ? 'selected' : '' ?>><?= esc(str_replace('_', ' ', ucfirst($option))) ?></option><?php endforeach ?></select></label><label>From<input name="from" type="date" value="<?= esc($from) ?>"></label><label>To<input name="to" type="date" value="<?= esc($to) ?>"></label><button type="submit">Apply filters</button></form><?php if (! $orders): ?><p>No orders found.</p><?php endif ?><?php foreach ($orders as $order): ?><article class="admin-item"><a href="<?= site_url($prefix . '/orders/' . $order['id']) ?>"><strong><?= esc($order['order_number']) ?></strong></a><p>Status: <?= esc(str_replace('_', ' ', $order['order_status'])) ?> · Total: <?= format_rupiah((string) $order['total']) ?></p></article><?php endforeach ?><div class="pagination"><?= $pager->links() ?></div></div><?= $this->endSection() ?>
